import{_ as o,o as r,c as i,a5 as t,j as e}from"./chunks/framework.B6tQOu6W.js";const l="/assets/demo2.CsH4gAuh.jpg",s="/assets/demo.DpdGXHnd.jpg",b=JSON.parse('{"title":"DAMP : Docker Apache MySQL PHP","description":"","frontmatter":{},"headers":[],"relativePath":"cheatsheets/damp/index.md","filePath":"cheatsheets/damp/index.md","lastUpdated":1704112852000}'),n={name:"cheatsheets/damp/index.md"};function c(u,a,d,m,p,h){return r(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="damp-docker-apache-mysql-php" tabindex="-1">DAMP : Docker Apache MySQL PHP <a class="header-anchor" href="#damp-docker-apache-mysql-php" aria-label="Permalink to &quot;DAMP : Docker Apache MySQL PHP&quot;">​</a></h1><p>Document présentant l&#39;installation de Docker, Apache, MySQL et PHP.</p><details class="details custom-block"><summary>Sommaire</summary><nav class="table-of-contents"><ul><li><a href="#introduction">Introduction</a><ul><li><a href="#que-contient-damp">Que contient DAMP ?</a></li><li><a href="#damp-c-est-deux-choses">DAMP c&#39;est deux choses</a></li></ul></li><li><a href="#prerequis">Prérequis</a></li><li><a href="#installation-lancement">Installation &amp; Lancement</a></li><li><a href="#utilisation">Utilisation</a></li><li><a href="#configuration">Configuration</a></li><li><a href="#ou-sont-les-fichiers">Où sont les fichiers ?</a></li><li><a href="#faq">FAQ</a><ul><li><a href="#comment-acceder-a-phpmyadmin">Comment accéder à PHPMyAdmin ?</a></li><li><a href="#comment-acceder-a-mongodb">Comment accéder à MongoDB ?</a></li><li><a href="#comment-acceder-a-mariadb">Comment accéder à MariaDB ?</a></li><li><a href="#comment-acceder-a-php">Comment accéder à PHP ?</a></li><li><a href="#comment-acceder-a-mailhog">Comment accéder à MailHog ?</a></li><li><a href="#est-ce-open-source">Est-ce Open Source ?</a></li><li><a href="#comment-puis-je-contribuer">Comment puis-je contribuer ?</a></li><li><a href="#comment-puis-je-vous-contacter">Comment puis-je vous contacter ?</a></li></ul></li></ul></nav></details><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>DAMP est un acronyme pour Docker Apache MySQL PHP. Il s&#39;agit d&#39;un environnement de développement pour les applications web. Il repose sur Docker et permet de créer un environnement de développement en quelques minutes.</p><h3 id="que-contient-damp" tabindex="-1">Que contient DAMP ? <a class="header-anchor" href="#que-contient-damp" aria-label="Permalink to &quot;Que contient DAMP ?&quot;">​</a></h3><p>DAMP contient les éléments suivants :</p><ul><li>PHP 8.2.7</li><li>MariaDB 10.9</li><li>PHPMyAdmin (dernière version)</li><li>MongoDB (dernière version)</li><li>MailHog (dernière version, serveur SMTP pour le développement)</li></ul><h3 id="damp-c-est-deux-choses" tabindex="-1">DAMP c&#39;est deux choses <a class="header-anchor" href="#damp-c-est-deux-choses" aria-label="Permalink to &quot;DAMP c&#39;est deux choses&quot;">​</a></h3><ul><li>Un stack via Docker Compose pour créer un environnement de développement.</li><li>Une interface graphique pour gérer les conteneurs (Démarrer, arrêter, etc.).</li></ul><div class="tip custom-block"><p class="custom-block-title">L&#39;interface graphique</p><p>L&#39;interface graphique est optionnelle, vous pouvez très bien utiliser DAMP sans l&#39;interface graphique en utilisant uniquement le script <code>startup.sh</code>.</p><p>👋 Je vous conseille vivement, d&#39;utiliser l&#39;interface en ligne de commande, elle est plus simple à utiliser et plus rapide à démarrer.</p></div><h2 id="prerequis" tabindex="-1">Prérequis <a class="header-anchor" href="#prerequis" aria-label="Permalink to &quot;Prérequis&quot;">​</a></h2><p>Pour fonctionner, vous devez avoir installé Docker et Docker Compose sur votre machine. Pour cela, il vous suffit d&#39;installer Docker Desktop :</p><ul><li><a href="https://docs.docker.com/get-docker/" target="_blank" rel="noreferrer">Installer Docker</a></li></ul><div class="tip custom-block"><p class="custom-block-title">Docker Desktop</p><p>Il est possible que Docker Desktop vous demande de créer un compte. Vous pouvez le faire, mais ce n&#39;est pas obligatoire.</p><p>Il est également possible que Docker Desktop vous demande de mettre à jour votre WSL. Pour cela, il vous suffit de suivre les instructions :</p><ul><li>Ouvrir un terminal (cmd, powershell, etc.)</li><li>Exécuter la commande suivante : <code>wsl --update</code></li></ul></div><h2 id="installation-lancement" tabindex="-1">Installation &amp; Lancement <a class="header-anchor" href="#installation-lancement" aria-label="Permalink to &quot;Installation &amp; Lancement&quot;">​</a></h2><p><img src="'+l+'" alt="CLI" loading="lazy"></p><p>L&#39;interface graphique n&#39;est pas pré-compilée pour Linux et MacOS. Vous pouvez <a href="https://github.com/c4software/DAMP" target="_blank" rel="noreferrer">la compiler vous même</a>, mais je vous conseille d&#39;utiliser la version en ligne de commande :</p><ul><li><ol><li><a href="https://github.com/c4software/DAMP-docker-stack/archive/refs/tags/1.1.zip" target="_blank" rel="noreferrer">Télécharger la stack docker</a>.</li></ol></li><li><ol start="2"><li>Lancer Docker.</li></ol></li><li><ol start="2"><li>Éxraire l&#39;archive de DAMP.</li></ol></li><li><ol start="3"><li>Plusieurs solutions s&#39;offrent à vous :</li></ol><ul><li>Sous Windows : <code>startup.bat</code> (lancement sans gestion des ports dynamiques) <strong>RECOMMANDÉ</strong></li><li>Sous Windows : <code>startup.ps1</code> (lancement avec gestion des ports dynamiques)</li><li>Sous Linux / MacOS : <code>startup.sh</code> (lancement avec gestion des ports dynamiques)</li></ul></li></ul><div class="tip custom-block"><p class="custom-block-title">Première utilisation</p><p>Lors de la première utilisation, les images sont téléchargées et préparées. Cela peut prendre plusieurs minutes. Vous pouvez suivre l&#39;avancement dans le terminal.</p></div><details class="details custom-block"><summary>Installation GUI (Windows uniquement, non recommandé)</summary><p><img src="'+s+'" alt="GUI" loading="lazy"></p><p>Pour installer DAMP, il suffit de :</p><ul><li><ol><li><a href="https://github.com/c4software/DAMP/raw/master/distribuable/win-1.0.zip" target="_blank" rel="noreferrer">Télécharger DAMP</a></li></ol></li><li><ol start="2"><li>Décompresser l&#39;archive.</li></ol></li><li><ol start="3"><li>Lancer le <code>damp.exe</code>.</li></ol></li></ul><p>Le premier démarrage peut prendre plusieurs minutes, le temps de télécharger les images Docker. Vous pouvez utiliser le bouton <code>Refresh</code> pour actualiser l&#39;état. Vous pouvez également ouvrir la feneêtre de Docker Desktop pour suivre l&#39;avancement (dans la partie Conteneurs).</p></details><h2 id="utilisation" tabindex="-1">Utilisation <a class="header-anchor" href="#utilisation" aria-label="Permalink to &quot;Utilisation&quot;">​</a></h2><p><em>Démo interface en ligne de commande :</em></p>',23),e("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/n3xNIprTFMU",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:""},null,-1),e("details",{class:"details custom-block"},[e("summary",null,"Utilisation GUI (Windows uniquement, non recommandé)"),e("p",null,[e("em",null,"Démo interface graphique :")]),e("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/5KvGDLrcasw",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:""})],-1),t('<h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>La configuration de DAMP se fait en modifiant les fichiers :</p><ul><li><code>docker-compose.yml</code> : Contient la configuration des conteneurs</li><li><code>dockerfiles/php.dockerfile</code> : Contient la configuration de PHP (extensions, etc.)</li></ul><p>La configuration de l&#39;interface graphique se fait en modifiant le fichier <code>configuration.yaml</code> :</p><ul><li><code>home</code> : Chemin <strong>absolu</strong> vers le dossier contenant le fichier <code>docker-compose.yml</code>.</li><li><code>dockerStackHome</code>: Chemin <strong>absolu</strong> ou <strong>relatif</strong> vers les dossiers qui seront montés dans les conteneurs. (vous pouvez laisser <code>./</code>, cela correspond au dossier contenant le fichier <code>docker-compose.yml</code>)</li><li><code>services</code> : Liste des services à afficher dans l&#39;interface graphique.</li></ul><h2 id="ou-sont-les-fichiers" tabindex="-1">Où sont les fichiers ? <a class="header-anchor" href="#ou-sont-les-fichiers" aria-label="Permalink to &quot;Où sont les fichiers ?&quot;">​</a></h2><p>Vos fichiers Web doivent être placés dans le dossier <code>data/htdocs</code>. Ce dossier est monté dans le conteneur Apache.</p><p>Ils seront ensuite accessibles via l&#39;adresse spécifiée dans la configuration de l&#39;interface graphique ou dans le terminal.</p><p>Vous avez de base un fichier <code>index.php</code> qui affiche le <code>phpinfo()</code>.</p><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><h3 id="comment-acceder-a-phpmyadmin" tabindex="-1">Comment accéder à PHPMyAdmin ? <a class="header-anchor" href="#comment-acceder-a-phpmyadmin" aria-label="Permalink to &quot;Comment accéder à PHPMyAdmin ?&quot;">​</a></h3><p>PHPMyAdmin est accessible à l&#39;adresse suivante : <a href="http://localhost:9090" target="_blank" rel="noreferrer">http://localhost:9090</a>. Cette information est également disponible dans l&#39;interface graphique ou dans le terminal.</p><h3 id="comment-acceder-a-mongodb" tabindex="-1">Comment accéder à MongoDB ? <a class="header-anchor" href="#comment-acceder-a-mongodb" aria-label="Permalink to &quot;Comment accéder à MongoDB ?&quot;">​</a></h3><p>MongoDB est accessible à l&#39;adresse suivante : <a href="http://localhost:27017" target="_blank" rel="noreferrer">http://localhost:27017</a>. Cette information est également disponible dans l&#39;interface graphique ou dans le terminal.</p><p>🚨 MongoDB n&#39;est pas démarré par défaut, il faut le démarrer dans l&#39;interface graphique ou dans le terminal. 🚨</p><h3 id="comment-acceder-a-mariadb" tabindex="-1">Comment accéder à MariaDB ? <a class="header-anchor" href="#comment-acceder-a-mariadb" aria-label="Permalink to &quot;Comment accéder à MariaDB ?&quot;">​</a></h3><p>MariaDB est accessible via le port <code>3306</code> sur l&#39;adresse <code>localhost</code>. Si vous souhaitez utiliser un client graphique, vous pouvez utiliser <a href="https://dbeaver.io/" target="_blank" rel="noreferrer">DBeaver</a> ou PHPMyAdmin disponible à l&#39;adresse suivante : <a href="http://localhost:9090" target="_blank" rel="noreferrer">http://localhost:9090</a>.</p><h3 id="comment-acceder-a-php" tabindex="-1">Comment accéder à PHP ? <a class="header-anchor" href="#comment-acceder-a-php" aria-label="Permalink to &quot;Comment accéder à PHP ?&quot;">​</a></h3><p>PHP est accessible à l&#39;adresse suivante : <a href="http://localhost:8080" target="_blank" rel="noreferrer">http://localhost:8080</a>. Cette information est également disponible dans l&#39;interface graphique ou dans le terminal.</p><p>⚠️ Les sources sont à mettre dans <code>data/htdocs</code>. ⚠️</p><h3 id="comment-acceder-a-mailhog" tabindex="-1">Comment accéder à MailHog ? <a class="header-anchor" href="#comment-acceder-a-mailhog" aria-label="Permalink to &quot;Comment accéder à MailHog ?&quot;">​</a></h3><p>MailHog est accessible à l&#39;adresse suivante : <a href="http://localhost:8025" target="_blank" rel="noreferrer">http://localhost:8025</a>. Cette information est également disponible dans l&#39;interface graphique ou dans le terminal.</p><p>MailHog expose également un serveur SMTP sur le port <code>1025</code> de l&#39;adresse <code>localhost</code>.</p><h3 id="est-ce-open-source" tabindex="-1">Est-ce Open Source ? <a class="header-anchor" href="#est-ce-open-source" aria-label="Permalink to &quot;Est-ce Open Source ?&quot;">​</a></h3><p>Oui DAMP est Open Source, vous pouvez retrouver le code source sur GitHub :</p><ul><li><a href="https://github.com/c4software/DAMP" target="_blank" rel="noreferrer">L&#39;interface graphique</a></li><li><a href="https://github.com/c4software/DAMP-docker-stack" target="_blank" rel="noreferrer">La Stack Docker (et le script de démarrage)</a></li></ul><h3 id="comment-puis-je-contribuer" tabindex="-1">Comment puis-je contribuer ? <a class="header-anchor" href="#comment-puis-je-contribuer" aria-label="Permalink to &quot;Comment puis-je contribuer ?&quot;">​</a></h3><p>Vous pouvez contribuer de plusieurs manières :</p><ul><li>En utilisant DAMP et en remontant les bugs.</li><li>En remontant les bugs sur GitHub.</li><li>En proposant des améliorations sur GitHub.</li><li>En proposant des améliorations sur le Slack de la classe.</li></ul><h3 id="comment-puis-je-vous-contacter" tabindex="-1">Comment puis-je vous contacter ? <a class="header-anchor" href="#comment-puis-je-vous-contacter" aria-label="Permalink to &quot;Comment puis-je vous contacter ?&quot;">​</a></h3><p>Vous pouvez me contacter via :</p><ul><li><a href="https://twitter.com/c4software" target="_blank" rel="noreferrer">Twitter</a></li></ul>',32)])])}const g=o(n,[["render",c]]);export{b as __pageData,g as default};
